// Security hardened with input validation and resource limits

use crate::CompileError;

// Security limits
const MAX_INPUT_SIZE: usize = 10_000_000;        // 10MB max
const MAX_IDENTIFIER_LENGTH: usize = 10_000;     // 10K chars max
const MAX_STRING_LENGTH: usize = 1_000_000;      // 1MB max
const MAX_NUMBER_LENGTH: usize = 100;            // 100 digits max

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    // Keywords
    Fn,
    Let,
    If,
    Else,
    Match,
    Return,
    Type,
    Mut,

    // Identifiers and literals
    Identifier(String),
    Integer(i64),
    Float(f64),
    String(String),
    True,
    False,

    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Assign,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
    And,
    Or,
    Not,
    Arrow,      // ->
    FatArrow,   // =>
    Pipe,       // |

    // Delimiters
    LParen,
    RParen,
    LBrace,
    RBrace,
    LBracket,
    RBracket,
    Comma,
    Dot,
    Colon,
    Semicolon,

    // Special
    Eof,
}

pub struct Lexer {
    input: Vec<char>,
    pos: usize,
    line: usize,
    column: usize,
}

