    let lexer = SecureLexer::new(&source).unwrap();
    let tokens = lexer.tokenize().unwrap();
    let parser = Parser::new(tokens).unwrap();
    let result = parser.parse();

    // 깊이 제한으로 인한 에러 예상
    assert!(result.is_err(), "깊이 제한 적용 안 됨");
}

#[test]
fn test_parse_token_limit() {
    // 매우 많은 토큰 생성
    let mut source = String::from("fn test() -> i32 { return ");
    for i in 0..200000 {
        source.push_str(&format!("{} + ", i));
    }
    source.push_str("0; }");

    let lexer = SecureLexer::new(&source).unwrap();
    let tokens = lexer.tokenize().unwrap();
    let result = Parser::new(tokens);

    // 토큰 수 제한으로 인한 에러 예상
    assert!(result.is_err(), "토큰 수 제한 적용 안 됨");
}

#[test]
fn test_parse_simple_fibonacci() {
    let source = r#"
