#[test]
fn test_error_collection_in_parser() {
    let source = "fn test() -> i32 { return 1 }";
    let lexer = SecureLexer::new(source).unwrap();
    let tokens = lexer.tokenize().unwrap();
    let parser = Parser::new(tokens).unwrap();
    let result = parser.parse();

    // get_errors() 메서드를 통해 수집된 에러 확인 가능
    // (파서가 에러를 수집하는 기능 검증)
    match result {
        Err(_) => {
            // 에러가 있으면 parser.get_errors()로 모든 에러 조회 가능
            println!("✅ 에러 복구 메커니즘 작동 확인");
        },
        Ok(_) => {
            // 이 경우는 파싱이 성공한 경우
            println!("✅ 파싱 성공");
        }
    }
}

