#[test]
fn test_parse_your_feature() {
    // 1단계: 소스 코드
    let source = "fn test() -> i32 { return 42; }";

    // 2단계: 렉싱
    let lexer = SecureLexer::new(source)
        .expect("렉서 생성 실패");
    let tokens = lexer.tokenize()
        .expect("토큰화 실패");

    // 3단계: 파싱
    let parser = Parser::new(tokens)
        .expect("파서 생성 실패");
    let result = parser.parse();

    // 4단계: 검증
    assert!(result.is_ok(), "파싱 실패");
    let program = result.unwrap();
    assert_eq!(program.definitions.len(), 1, "1개 정의 필요");
}
```

