// src/types.rs (신규)
#[derive(Debug, Clone, PartialEq)]
pub enum Type {
    // 기본 타입
    Integer,        // i32
    Float,          // f64
    String,         // String
    Boolean,        // bool

    // 복합 타입 (향후)
