use crate::ast::*;
use crate::types::Type;
use crate::symbols::SymbolTable;
use std::collections::HashMap;

/// 함수 시그니처
#[derive(Debug, Clone)]
pub struct FunctionSignature {
    pub name: String,
    pub params: Vec<(String, Type)>,
    pub return_type: Type,
}

/// 타입 검사 에러
#[derive(Debug, Clone)]
pub struct TypeError {
    pub message: String,
}

impl TypeError {
    pub fn new(message: String) -> Self {
        TypeError { message }
    }
}

impl std::fmt::Display for TypeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "타입 에러: {}", self.message)
    }
}

/// 타입 검사를 수행하는 구조체
pub struct TypeChecker {
    symbol_table: SymbolTable,
    errors: Vec<TypeError>,
    function_signatures: HashMap<String, FunctionSignature>,
}

impl TypeChecker {
    /// 새로운 타입 검사기를 생성합니다
    pub fn new() -> Self {
        TypeChecker {
            symbol_table: SymbolTable::new(),
            errors: Vec::new(),
        }
    }

    /// 프로그램 전체를 타입 검사합니다
    pub fn check(&mut self, program: &Program) -> Result<(), Vec<TypeError>> {
        for definition in &program.definitions {
            if let Err(e) = self.check_definition(definition) {
                self.errors.push(e);
            }
        }

        if self.errors.is_empty() {
            Ok(())
        } else {
            Err(self.errors.clone())
        }
    }

    /// 정의를 타입 검사합니다
    fn check_definition(&mut self, def: &Definition) -> Result<(), TypeError> {
        match def {
            Definition::Function { name, params, body } => {
                self.symbol_table.enter_scope();

                // 매개변수를 심볼 테이블에 추가
                // 현재는 타입 정보가 없으므로 Unknown으로 설정
                for param in params {
                    self.symbol_table.define(
                        param.clone(),
                        Type::Unknown,
                        false,
                    ).map_err(|e| TypeError::new(e))?;
                }

                // 함수 본문 검사
                for stmt in body {
                    self.check_statement(stmt)?;
                }

                self.symbol_table.exit_scope();
                Ok(())
            }
            Definition::TypeDef { name: _ } => {
                // 타입 정의는 현재 검사할 것이 없음
                Ok(())
            }
        }
    }

    /// 문장을 타입 검사합니다
    fn check_statement(&mut self, stmt: &Statement) -> Result<Type, TypeError> {
        match stmt {
            Statement::LetBinding { name, value } => {
                let value_type = self.check_expression(value)?;
                self.symbol_table.define(name.clone(), value_type.clone(), true)
                    .map_err(|e| TypeError::new(e))?;
                Ok(value_type)
            }
            Statement::Return(expr) => {
                self.check_expression(expr)
            }
            Statement::If {
                condition,
                then_branch,
                else_branch,
            } => {
                let cond_type = self.check_expression(condition)?;

                // 조건은 boolean이어야 함
                if cond_type != Type::Boolean && cond_type != Type::Unknown {
                    return Err(TypeError::new(
                        format!("조건은 bool 타입이어야 하지만 {:?}을(를) 받음", cond_type),
                    ));
                }

                // then 브랜치 검사
                for then_stmt in then_branch {
                    self.check_statement(then_stmt)?;
                }

                // else 브랜치 검사
                if let Some(else_stmts) = else_branch {
                    for else_stmt in else_stmts {
                        self.check_statement(else_stmt)?;
                    }
                }

                Ok(Type::Unknown)
            }
            Statement::Expression(expr) => {
                self.check_expression(expr)
            }
        }
    }

    /// 표현식을 타입 검사합니다
    pub fn check_expression(&mut self, expr: &Expression) -> Result<Type, TypeError> {
        match expr {
            Expression::Literal(lit) => {
                match lit {
                    Literal::Integer(_) => Ok(Type::Integer),
                    Literal::Float(_) => Ok(Type::Float),
                    Literal::String(_) => Ok(Type::String),
                    Literal::Boolean(_) => Ok(Type::Boolean),
                }
            }
            Expression::Variable(name) => {
                match self.symbol_table.get_type(name) {
                    Some(type_) => Ok(type_),
                    None => Err(TypeError::new(format!("정의되지 않은 변수: '{}'", name))),
                }
            }
            Expression::BinaryOp { op, left, right } => {
                let left_type = self.check_expression(left)?;
                let right_type = self.check_expression(right)?;

                self.check_binary_op(op, &left_type, &right_type)
            }
            Expression::UnaryOp { op, operand } => {
                let operand_type = self.check_expression(operand)?;
                self.check_unary_op(op, &operand_type)
            }
            Expression::FunctionCall { name: _, args } => {
                // 인자의 타입만 검사
                for arg in args {
                    self.check_expression(arg)?;
                }
                // 반환 타입은 Unknown (향후 함수 시그니처 검사 추가)
                Ok(Type::Unknown)
            }
            Expression::IfExpr {
                condition,
                then_expr,
                else_expr,
            } => {
                let cond_type = self.check_expression(condition)?;

                if cond_type != Type::Boolean && cond_type != Type::Unknown {
                    return Err(TypeError::new(
                        format!("조건은 bool 타입이어야 함, 받은 타입: {:?}", cond_type),
                    ));
                }

                let then_type = self.check_expression(then_expr)?;

                if let Some(else_expr) = else_expr {
                    let else_type = self.check_expression(else_expr)?;

                    // then과 else의 타입이 호환되어야 함
                    if then_type.is_compatible(&else_type) {
                        Ok(then_type)
                    } else {
                        Err(TypeError::new(format!(
                            "if 표현식의 분기 타입이 맞지 않음: {} vs {}",
                            then_type, else_type
                        )))
                    }
                } else {
                    Ok(then_type)
                }
            }
            Expression::Match { .. } => {
                // 향후 match 표현식 구현
                Ok(Type::Unknown)
            }
        }
    }

    /// 이항 연산을 타입 검사합니다
    fn check_binary_op(
        &self,
        op: &str,
        left_type: &Type,
        right_type: &Type,
    ) -> Result<Type, TypeError> {
        match op {
            // 산술 연산자
            "Plus" | "Minus" | "Star" | "Slash" | "Percent" => {
                if left_type.is_numeric() && right_type.is_numeric() {
                    // 결과 타입은 더 넓은 타입
                    match (left_type, right_type) {
                        (Type::Float, _) | (_, Type::Float) => Ok(Type::Float),
                        _ => Ok(left_type.clone()),
                    }
                } else if left_type == Type::Unknown || right_type == Type::Unknown {
                    Ok(Type::Unknown)
                } else {
                    Err(TypeError::new(format!(
                        "산술 연산 '{}'은 숫자 타입이어야 하지만 {} 과 {} 을(를) 받음",
                        op, left_type, right_type
                    )))
                }
            }
            // 비교 연산자
            "Eq" | "Ne" | "Lt" | "Le" | "Gt" | "Ge" => {
                if left_type.is_compatible(right_type) {
                    Ok(Type::Boolean)
                } else if left_type == Type::Unknown || right_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "비교 연산 '{}'에서 호환되지 않는 타입: {} 과 {}",
                        op, left_type, right_type
                    )))
                }
            }
            // 논리 연산자
            "And" | "Or" => {
                if left_type == Type::Boolean && right_type == Type::Boolean {
                    Ok(Type::Boolean)
                } else if left_type == Type::Unknown || right_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "논리 연산 '{}'은 bool 타입이어야 하지만 {} 과 {} 을(를) 받음",
                        op, left_type, right_type
                    )))
                }
            }
            _ => Err(TypeError::new(format!("알 수 없는 연산자: '{}'", op))),
        }
    }

    /// 단항 연산을 타입 검사합니다
    fn check_unary_op(&self, op: &str, operand_type: &Type) -> Result<Type, TypeError> {
        match op {
            "Not" => {
                if operand_type == Type::Boolean || operand_type == Type::Unknown {
                    Ok(Type::Boolean)
                } else {
                    Err(TypeError::new(format!(
                        "! 연산은 bool 타입이어야 하지만 {} 을(를) 받음",
                        operand_type
                    )))
                }
            }
            "Minus" => {
                if operand_type.is_numeric() || operand_type == Type::Unknown {
                    Ok(operand_type.clone())
                } else {
                    Err(TypeError::new(format!(
                        "- 연산은 숫자 타입이어야 하지만 {} 을(를) 받음",
                        operand_type
                    )))
                }
            }
            _ => Err(TypeError::new(format!("알 수 없는 단항 연산자: '{}'", op))),
        }
    }

    /// 모든 타입 검사 에러를 반환합니다
    pub fn get_errors(&self) -> &[TypeError] {
        &self.errors
    }

    /// 심볼 테이블의 현재 심볼들을 반환합니다
    pub fn current_symbols(&self) -> Vec<(String, Type)> {
        self.symbol_table
            .current_symbols()
            .into_iter()
            .map(|s| (s.name, s.type_))
            .collect()
    }
}

impl Default for TypeChecker {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_type_checker_new() {
        let checker = TypeChecker::new();
        assert_eq!(checker.get_errors().len(), 0);
    }

    #[test]
    fn test_check_integer_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Integer(42));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_string_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::String("hello".to_string()));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::String));
    }

    #[test]
    fn test_check_boolean_literal() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Literal(Literal::Boolean(true));
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_undefined_variable() {
        let mut checker = TypeChecker::new();
        let expr = Expression::Variable("undefined".to_string());
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_integers() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_arithmetic_incompatible() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::String("hello".to_string()))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_comparison() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Eq".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Integer(2))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_logical_operation() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "And".to_string(),
            left: Box::new(Expression::Literal(Literal::Boolean(true))),
            right: Box::new(Expression::Literal(Literal::Boolean(false))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_not() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Not".to_string(),
            operand: Box::new(Expression::Literal(Literal::Boolean(true))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Boolean));
    }

    #[test]
    fn test_check_unary_minus() {
        let mut checker = TypeChecker::new();
        let expr = Expression::UnaryOp {
            op: "Minus".to_string(),
            operand: Box::new(Expression::Literal(Literal::Integer(42))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::Integer(2)))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Integer));
    }

    #[test]
    fn test_check_if_expression_type_mismatch() {
        let mut checker = TypeChecker::new();
        let expr = Expression::IfExpr {
            condition: Box::new(Expression::Literal(Literal::Boolean(true))),
            then_expr: Box::new(Expression::Literal(Literal::Integer(1))),
            else_expr: Some(Box::new(Expression::Literal(Literal::String("hello".to_string())))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }

    #[test]
    fn test_check_arithmetic_mixed_numeric() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "Plus".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Float(2.5))),
        };
        let result = checker.check_expression(&expr);
        assert_eq!(result, Ok(Type::Float));
    }

    #[test]
    fn test_check_logical_operation_invalid() {
        let mut checker = TypeChecker::new();
        let expr = Expression::BinaryOp {
            op: "And".to_string(),
            left: Box::new(Expression::Literal(Literal::Integer(1))),
            right: Box::new(Expression::Literal(Literal::Boolean(true))),
        };
        let result = checker.check_expression(&expr);
        assert!(result.is_err());
    }
}

