        else_expr: Option<Box<Expression>>,
    },
    Match {
        expr: Box<Expression>,
        patterns: Vec<(String, Box<Expression>)>,
    },
}

#[derive(Debug, Clone)]
pub enum Literal {
    Integer(i64),
