                elements: vec![
                    Expression::Literal(Literal::Integer(2)),
                    Expression::Literal(Literal::String("two".to_string())),
                ],
            },
        ],
    };

    let result = checker.check_expression(&expr);
    assert!(result.is_ok());

    let expected = Type::Array {
