// IR (Intermediate Representation) 정의
// Phase 4: 코드 생성

use crate::types::Type;
use std::fmt;

/// IR 노드는 AST를 더 낮은 수준의 표현으로 변환합니다
#[derive(Debug, Clone, PartialEq)]
pub enum IRNode {
    // === 리터럴 값 ===
    IntLiteral(i64),
    FloatLiteral(f64),
    StringLiteral(String),
    BoolLiteral(bool),

    // === 변수 ===
    Variable(String),

    // === 연산 ===
    BinaryOp {
        op: String,
        left: Box<IRNode>,
        right: Box<IRNode>,
    },
    UnaryOp {
        op: String,
        operand: Box<IRNode>,
    },

    // === 제어 흐름 ===
    If {
        condition: Box<IRNode>,
        then_block: Vec<IRNode>,
        else_block: Option<Vec<IRNode>>,
    },

    // === 함수 ===
    FunctionCall {
        name: String,
        args: Vec<IRNode>,
    },

    // === 배열/튜플 ===
    Array {
        elements: Vec<IRNode>,
    },
    Index {
        expr: Box<IRNode>,
        index: Box<IRNode>,
    },
    Tuple {
        elements: Vec<IRNode>,
    },

    // === 변수 할당 ===
    Assign {
        name: String,
        value: Box<IRNode>,
    },

    // === 반환 ===
    Return(Box<IRNode>),

    // === 다중 명령 ===
    Block(Vec<IRNode>),
}

/// IR 함수 정의
#[derive(Debug, Clone)]
pub struct IRFunction {
    pub name: String,
    pub params: Vec<(String, Type)>,
    pub return_type: Type,
    pub body: Vec<IRNode>,
}

/// IR 프로그램 (함수들의 모음)
#[derive(Debug, Clone)]
pub struct IRProgram {
    pub functions: Vec<IRFunction>,
    pub main: Vec<IRNode>,
}

impl IRNode {
    /// 이 IR 노드가 값을 반환하는지 확인합니다
    pub fn returns_value(&self) -> bool {
        match self {
            IRNode::IntLiteral(_)
            | IRNode::FloatLiteral(_)
            | IRNode::StringLiteral(_)
            | IRNode::BoolLiteral(_)
            | IRNode::Variable(_)
            | IRNode::BinaryOp { .. }
            | IRNode::UnaryOp { .. }
            | IRNode::FunctionCall { .. }
            | IRNode::Array { .. }
            | IRNode::Index { .. }
            | IRNode::Tuple { .. } => true,

            IRNode::If { .. } | IRNode::Assign { .. } | IRNode::Return(_) | IRNode::Block(_) => {

