// 값 표현 (Value Representation)
// Phase 5: 런타임

use std::collections::HashMap;
use std::fmt;
use crate::ir::IRNode;

/// 런타임 값 표현
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    /// 정수 (64-bit)
    Integer(i64),

    /// 실수 (64-bit)
    Float(f64),

    /// 문자열
    String(String),

    /// 불린
    Boolean(bool),

    /// 배열
    Array(Vec<Value>),

    /// 튜플
    Tuple(Vec<Value>),

    /// 함수
    Function {
        name: String,
        params: Vec<String>,
        body: Vec<IRNode>,
    },

    /// 빈 값
    None,
}

impl Value {
    /// 값의 타입 이름을 반환합니다
    pub fn type_name(&self) -> &str {
        match self {
            Value::Integer(_) => "integer",
            Value::Float(_) => "float",
            Value::String(_) => "string",
            Value::Boolean(_) => "boolean",
            Value::Array(_) => "array",
            Value::Tuple(_) => "tuple",
            Value::Function { .. } => "function",
            Value::None => "none",
        }
    }

    /// 값을 정수로 변환합니다
    pub fn to_integer(&self) -> Option<i64> {
        match self {
            Value::Integer(n) => Some(*n),
            Value::Float(f) => Some(*f as i64),
            Value::Boolean(b) => Some(if *b { 1 } else { 0 }),
            _ => None,
        }
    }

    /// 값을 실수로 변환합니다
    pub fn to_float(&self) -> Option<f64> {
        match self {
            Value::Integer(n) => Some(*n as f64),
            Value::Float(f) => Some(*f),
            Value::Boolean(b) => Some(if *b { 1.0 } else { 0.0 }),
            _ => None,
        }
    }

    /// 값을 문자열로 변환합니다
    pub fn to_string(&self) -> String {
        match self {
            Value::Integer(n) => n.to_string(),
            Value::Float(f) => f.to_string(),
            Value::String(s) => s.clone(),
            Value::Boolean(b) => b.to_string(),
            Value::Array(arr) => {
                let items: Vec<String> = arr.iter().map(|v| v.to_string()).collect();
                format!("[{}]", items.join(", "))
            }
            Value::Tuple(tuple) => {
                let items: Vec<String> = tuple.iter().map(|v| v.to_string()).collect();
                format!("({})", items.join(", "))
            }
            Value::Function { name, .. } => format!("<fn {}>", name),
            Value::None => "none".to_string(),
        }
    }

    /// 값을 불린으로 변환합니다
    pub fn to_bool(&self) -> bool {
        match self {
            Value::Boolean(b) => *b,
            Value::Integer(n) => *n != 0,
            Value::Float(f) => *f != 0.0,
            Value::String(s) => !s.is_empty(),
            Value::Array(a) => !a.is_empty(),
            Value::None => false,
            _ => true,
        }
    }

    /// 값이 같은지 비교합니다
    pub fn equals(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Integer(a), Value::Integer(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::String(a), Value::String(b)) => a == b,
            (Value::Boolean(a), Value::Boolean(b)) => a == b,
            (Value::None, Value::None) => true,
            // 다른 타입 간 비교
            (Value::Integer(a), Value::Float(b)) => *a as f64 == *b,
            (Value::Float(a), Value::Integer(b)) => *a == *b as f64,
            _ => false,
        }
    }

    /// 배열 인덱스 접근
    pub fn get_index(&self, index: usize) -> Option<Value> {
        match self {
            Value::Array(arr) => arr.get(index).cloned(),
            Value::String(s) => {
                s.chars()
                    .nth(index)
                    .map(|c| Value::String(c.to_string()))
            }
            Value::Tuple(t) => t.get(index).cloned(),
            _ => None,
        }
    }

    /// 배열 길이 반환
    pub fn len(&self) -> Option<usize> {
        match self {
            Value::Array(arr) => Some(arr.len()),
            Value::String(s) => Some(s.len()),
            Value::Tuple(t) => Some(t.len()),
            _ => None,
        }
    }

    /// 배열에 요소 추가
    pub fn push(&mut self, value: Value) -> Result<(), String> {
        match self {
            Value::Array(arr) => {
                arr.push(value);
                Ok(())
            }
            _ => Err(format!("Cannot push to {}", self.type_name())),
        }
    }
}

