// Phase 5 Stage 3: 컴파일러 통합 및 최적화 테스트
// Compiler Integration & Optimization Testing

use fv_lang::{Compiler, CompileError, Value, Runtime, IRNode};

#[test]
fn test_compiler_create() {
    let compiler = Compiler::new();
    // 컴파일러 생성 검증
    assert!(compiler.runtime().stack().depth() >= 1);
}

#[test]
fn test_compiler_error_handling_structure() {
    // CompileError 구조 검증
    let err1 = CompileError::LexerError("test error".to_string());
    assert_eq!(err1.to_string(), "Lexer error: test error");

    let err2 = CompileError::ParserError("parse failed".to_string());
    assert_eq!(err2.to_string(), "Parser error: parse failed");

    let err3 = CompileError::TypeError("type mismatch".to_string());
    assert_eq!(err3.to_string(), "Type error: type mismatch");

    let err4 = CompileError::CodegenError("codegen failed".to_string());
    assert_eq!(err4.to_string(), "Code generation error: codegen failed");

    let err5 = CompileError::RuntimeError("runtime error".to_string());
    assert_eq!(err5.to_string(), "Runtime error: runtime error");
}

#[test]
fn test_runtime_simple_execution() {
    let mut runtime = Runtime::new();

    // 간단한 덧셈: 5 + 3 = 8
    let left = IRNode::Literal {
        value: Value::Integer(5),
    };
    let right = IRNode::Literal {
        value: Value::Integer(3),
    };
    let add = IRNode::BinaryOp {
        op: "+".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[add]);
    assert_eq!(result, Ok(Value::Integer(8)));
}

#[test]
fn test_runtime_complex_expression() {
    let mut runtime = Runtime::new();

    // (10 + 5) * 2 = 30
    let inner_left = IRNode::Literal {
        value: Value::Integer(10),
    };
    let inner_right = IRNode::Literal {
        value: Value::Integer(5),
    };
    let add = IRNode::BinaryOp {
        op: "+".to_string(),
        left: Box::new(inner_left),
        right: Box::new(inner_right),
    };

    let mul_right = IRNode::Literal {
        value: Value::Integer(2),
    };
    let mul = IRNode::BinaryOp {
        op: "*".to_string(),
        left: Box::new(add),
        right: Box::new(mul_right),
    };

    let result = runtime.execute(&[mul]);
    assert_eq!(result, Ok(Value::Integer(30)));
}

#[test]
fn test_runtime_boolean_logic() {
    let mut runtime = Runtime::new();

    // true && false = false
    let left = IRNode::Literal {
        value: Value::Boolean(true),
    };
    let right = IRNode::Literal {
        value: Value::Boolean(false),
    };
    let and = IRNode::BinaryOp {
        op: "&&".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[and]);
    assert_eq!(result, Ok(Value::Boolean(false)));
}

#[test]
fn test_runtime_comparison_chain() {
    let mut runtime = Runtime::new();

    // 10 < 20 = true
    let left = IRNode::Literal {
        value: Value::Integer(10),
    };
    let right = IRNode::Literal {
        value: Value::Integer(20),
    };
    let lt = IRNode::BinaryOp {
        op: "<".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[lt]);
    assert_eq!(result, Ok(Value::Boolean(true)));
}

#[test]
fn test_runtime_float_arithmetic() {
    let mut runtime = Runtime::new();

    // 3.5 * 2.0 = 7.0
    let left = IRNode::Literal {
        value: Value::Float(3.5),
    };
    let right = IRNode::Literal {
        value: Value::Float(2.0),
    };
    let mul = IRNode::BinaryOp {
        op: "*".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[mul]);
    match result {
        Ok(Value::Float(f)) => assert!((f - 7.0).abs() < 0.001),
        _ => panic!("Expected float result"),
    }
}

#[test]
fn test_runtime_type_safety() {
    let mut runtime = Runtime::new();

    // "text" + 42 → TypeError
    let left = IRNode::Literal {
        value: Value::String("text".to_string()),
    };
    let right = IRNode::Literal {
        value: Value::Integer(42),
    };
    let add = IRNode::BinaryOp {
        op: "+".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[add]);
    assert!(result.is_err()); // 타입 에러 발생
}

#[test]
fn test_runtime_stack_management() {
    let mut runtime = Runtime::new();

    // 초기 스택 깊이 확인
    let initial_depth = runtime.stack().depth();
    assert_eq!(initial_depth, 1); // 글로벌 프레임

    // 실행 후에도 스택 정리 확인
    let lit = IRNode::Literal {
        value: Value::Integer(42),
    };
    let _ = runtime.execute(&[lit]);
    let final_depth = runtime.stack().depth();
    assert_eq!(final_depth, 1); // 여전히 글로벌 프레임만
}

#[test]
fn test_runtime_memory_allocation() {
    let mut runtime = Runtime::new();

    // 힙의 초기 크기
    let initial_heap_size = runtime.heap().size();

    // 메모리 할당
    let addr = runtime.heap_mut().allocate(Value::Integer(42));
    assert!(addr >= 0);

    // 힙 크기 증가 확인
    let new_heap_size = runtime.heap().size();
    assert!(new_heap_size >= initial_heap_size);
}

#[test]
fn test_compilation_result_display() {
    let result = fv_lang::CompilationResult {
        tokens: 100,
        ast_nodes: 50,
        ir_nodes: 120,
        success: true,
    };

    let summary = result.summary();
    assert!(summary.contains("✅"));
    assert!(summary.contains("Tokens: 100"));
    assert!(summary.contains("AST Nodes: 50"));
    assert!(summary.contains("IR Nodes: 120"));
}

#[test]
fn test_runtime_multiple_operations() {
    let mut runtime = Runtime::new();

    // 5 + 3
    let add_result = {
        let left = IRNode::Literal {
            value: Value::Integer(5),
        };
        let right = IRNode::Literal {
            value: Value::Integer(3),
        };
        let add = IRNode::BinaryOp {
            op: "+".to_string(),
            left: Box::new(left),
            right: Box::new(right),
        };
        runtime.execute(&[add])
    };
    assert_eq!(add_result, Ok(Value::Integer(8)));

    // * 2
    let mut runtime2 = Runtime::new();
    let mul_result = {
        let left = IRNode::Literal {
            value: Value::Integer(8),
        };
        let right = IRNode::Literal {
            value: Value::Integer(2),
        };
        let mul = IRNode::BinaryOp {
            op: "*".to_string(),
            left: Box::new(left),
            right: Box::new(right),
        };
        runtime2.execute(&[mul])
    };
    assert_eq!(mul_result, Ok(Value::Integer(16)));
}

#[test]
fn test_runtime_negative_numbers() {
    let mut runtime = Runtime::new();

    // -42
    let lit = IRNode::Literal {
        value: Value::Integer(42),
    };
    let neg = IRNode::UnaryOp {
        op: "-".to_string(),
        operand: Box::new(lit),
    };

    let result = runtime.execute(&[neg]);
    assert_eq!(result, Ok(Value::Integer(-42)));
}

#[test]
fn test_runtime_logical_not() {
    let mut runtime = Runtime::new();

    // !(true) = false
    let lit = IRNode::Literal {
        value: Value::Boolean(true),
    };
    let not = IRNode::UnaryOp {
        op: "!".to_string(),
        operand: Box::new(lit),
    };

    let result = runtime.execute(&[not]);
    assert_eq!(result, Ok(Value::Boolean(false)));
}

#[test]
fn test_runtime_equality_check() {
    let mut runtime = Runtime::new();

    // 42 == 42 = true
    let left = IRNode::Literal {
        value: Value::Integer(42),
    };
    let right = IRNode::Literal {
        value: Value::Integer(42),
    };
    let eq = IRNode::BinaryOp {
        op: "==".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[eq]);
    assert_eq!(result, Ok(Value::Boolean(true)));
}

#[test]
fn test_runtime_modulo_operation() {
    let mut runtime = Runtime::new();

    // 17 % 5 = 2
    let left = IRNode::Literal {
        value: Value::Integer(17),
    };
    let right = IRNode::Literal {
        value: Value::Integer(5),
    };
    let modulo = IRNode::BinaryOp {
        op: "%".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[modulo]);
    assert_eq!(result, Ok(Value::Integer(2)));
}

#[test]
fn test_runtime_string_concatenation() {
    let mut runtime = Runtime::new();

    // "Hello " + "World" = "Hello World"
    let left = IRNode::Literal {
        value: Value::String("Hello ".to_string()),
    };
    let right = IRNode::Literal {
        value: Value::String("World".to_string()),
    };
    let concat = IRNode::BinaryOp {
        op: "+".to_string(),
        left: Box::new(left),
        right: Box::new(right),
    };

    let result = runtime.execute(&[concat]);
    match result {
        Ok(Value::String(s)) => assert_eq!(s, "Hello World"),
        _ => panic!("Expected string result"),
    }
}

#[test]
fn test_compiler_default() {
    let compiler = Compiler::default();
    assert!(compiler.runtime().stack().depth() >= 1);
}

#[test]
fn test_runtime_comparison_operators() {
    // Test all comparison operators
    let test_cases = vec![
        (10, 10, "==", true),
        (10, 11, "!=", true),
        (10, 20, "<", true),
        (20, 10, ">", true),
        (10, 10, "<=", true),
        (11, 10, ">=", true),
    ];

    for (left_val, right_val, op, expected) in test_cases {
        let mut runtime = Runtime::new();
        let left = IRNode::Literal {
            value: Value::Integer(left_val),
        };
        let right = IRNode::Literal {
            value: Value::Integer(right_val),
        };
        let comparison = IRNode::BinaryOp {
            op: op.to_string(),
            left: Box::new(left),
            right: Box::new(right),
        };

        let result = runtime.execute(&[comparison]);
        assert_eq!(result, Ok(Value::Boolean(expected)));
    }
}

