    }

    #[test]
    fn test_slice() {
        let arr = vec![
            Value::Integer(1),
            Value::Integer(2),
            Value::Integer(3),
            Value::Integer(4),
        ];
        let sliced = slice(&arr, 1, 3).unwrap();
        assert_eq!(sliced.len(), 2);
        assert!(matches!(&sliced[0], Value::Integer(2)));
        assert!(matches!(&sliced[1], Value::Integer(3)));
    }

    #[test]
    fn test_remove() {
        let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
        let removed = remove(&arr, 1).unwrap();
        assert_eq!(removed.len(), 2);
        assert!(matches!(&removed[0], Value::Integer(1)));
        assert!(matches!(&removed[1], Value::Integer(3)));
    }

    #[test]
    fn test_every() {
        let arr = vec![Value::Integer(2), Value::Integer(4), Value::Integer(6)];
        let all_even = every(&arr, |v| {
