/// 값이 정수 타입인지 확인합니다
pub fn is_integer(value: &Value) -> bool {
    matches!(value, Value::Integer(_))
}

/// 값이 실수 타입인지 확인합니다
pub fn is_float(value: &Value) -> bool {
    matches!(value, Value::Float(_))
}

/// 값이 문자열 타입인지 확인합니다
pub fn is_string(value: &Value) -> bool {
    matches!(value, Value::String(_))
}

/// 값이 불린 타입인지 확인합니다
pub fn is_boolean(value: &Value) -> bool {
    matches!(value, Value::Boolean(_))
}

/// 값이 배열 타입인지 확인합니다
pub fn is_array(value: &Value) -> bool {
    matches!(value, Value::Array(_))
}

/// 값이 튜플 타입인지 확인합니다
pub fn is_tuple(value: &Value) -> bool {
    matches!(value, Value::Tuple(_))
}

/// 값이 함수 타입인지 확인합니다
pub fn is_function(value: &Value) -> bool {
    matches!(value, Value::Function { .. })
}

/// 값이 None인지 확인합니다
pub fn is_none(value: &Value) -> bool {
    matches!(value, Value::None)
}

/// 값이 null/none이 아닌지 확인합니다
pub fn is_not_null(value: &Value) -> bool {
    !matches!(value, Value::None)
}

/// 문자열을 정수로 파싱합니다
pub fn parse_integer(s: &str) -> Option<i64> {
    s.trim().parse::<i64>().ok()
}

/// 문자열을 실수로 파싱합니다
pub fn parse_float(s: &str) -> Option<f64> {
    s.trim().parse::<f64>().ok()
}

/// 문자열을 불린으로 파싱합니다
pub fn parse_bool(s: &str) -> Option<bool> {
    match s.trim().to_lowercase().as_str() {
        "true" | "yes" | "1" => Some(true),
        "false" | "no" | "0" => Some(false),
        _ => None,
    }
}

/// 값이 truthy인지 확인합니다
pub fn is_truthy(value: &Value) -> bool {
    value.to_bool()
}

/// 값이 falsy인지 확인합니다
