// Phase 6 Stage 3: 고급 함수 & 통계 (Advanced Functions & Statistics) 테스트
// Advanced Math, Statistics, Random Functions Testing

use fv_lang::stdlib::advanced;
use fv_lang::Value;

// ============= 통계 함수 테스트 =============

#[test]
fn test_variance_basic() {
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    let var = advanced::variance(&arr).unwrap();
    assert!((var - 0.666666).abs() < 0.01);
}

#[test]
fn test_variance_constant() {
    // 모든 값이 같으면 분산은 0
    let arr = vec![Value::Integer(5), Value::Integer(5), Value::Integer(5)];
    let var = advanced::variance(&arr).unwrap();
    assert!(var < 0.0001);
}

#[test]
fn test_variance_empty() {
    let arr: Vec<Value> = vec![];
    assert_eq!(advanced::variance(&arr), None);
}

#[test]
fn test_variance_floats() {
    let arr = vec![Value::Float(1.5), Value::Float(2.5), Value::Float(3.5)];
    let var = advanced::variance(&arr).unwrap();
    assert!(var > 0.0);
}

#[test]
fn test_standard_deviation_basic() {
    let arr = vec![
        Value::Integer(2),
        Value::Integer(4),
        Value::Integer(4),
        Value::Integer(4),
        Value::Integer(5),
        Value::Integer(5),
        Value::Integer(7),
        Value::Integer(9),
    ];
    let stddev = advanced::standard_deviation(&arr).unwrap();
    assert!(stddev > 0.0);
}

#[test]
fn test_standard_deviation_empty() {
    let arr: Vec<Value> = vec![];
    assert_eq!(advanced::standard_deviation(&arr), None);
}

#[test]
fn test_median_odd_length() {
    let arr = vec![Value::Integer(1), Value::Integer(2), Value::Integer(3)];
    assert_eq!(advanced::median(&arr), Some(2.0));
}

#[test]
fn test_median_even_length() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
        Value::Integer(4),
    ];
    assert_eq!(advanced::median(&arr), Some(2.5));
}

#[test]
fn test_median_unsorted() {
    let arr = vec![
        Value::Integer(3),
        Value::Integer(1),
        Value::Integer(2),
    ];
    assert_eq!(advanced::median(&arr), Some(2.0));
}

#[test]
fn test_median_empty() {
    let arr: Vec<Value> = vec![];
    assert_eq!(advanced::median(&arr), None);
}

#[test]
fn test_mode_basic() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(2),
        Value::Integer(3),
    ];
    let mode = advanced::mode(&arr).unwrap();
    assert!(matches!(mode, Value::Integer(2)));
}

#[test]
fn test_mode_string() {
    let arr = vec![
        Value::String("a".to_string()),
        Value::String("b".to_string()),
        Value::String("b".to_string()),
    ];
    let mode = advanced::mode(&arr).unwrap();
    assert!(matches!(mode, Value::String(ref s) if s == "b"));
}

#[test]
fn test_mode_empty() {
    let arr: Vec<Value> = vec![];
    assert_eq!(advanced::mode(&arr), None);
}

// ============= 범위 함수 테스트 =============

#[test]
fn test_range_basic() {
    let arr = vec![Value::Integer(1), Value::Integer(5), Value::Integer(3)];
    assert_eq!(advanced::range(&arr), Some(4.0));
}

#[test]
fn test_range_negatives() {
    let arr = vec![Value::Integer(-10), Value::Integer(0), Value::Integer(10)];
    assert_eq!(advanced::range(&arr), Some(20.0));
}

#[test]
fn test_range_empty() {
    let arr: Vec<Value> = vec![];
    assert_eq!(advanced::range(&arr), None);
}

// ============= 정규화 함수 테스트 =============

#[test]
fn test_normalize_basic() {
    let arr = vec![Value::Integer(0), Value::Integer(5), Value::Integer(10)];
    let normalized = advanced::normalize(&arr).unwrap();
    assert_eq!(normalized.len(), 3);
    // 첫 번째: (0-0)/10 = 0.0
    if let Value::Float(f) = &normalized[0] {
        assert!((*f - 0.0).abs() < 0.001);
    }
    // 마지막: (10-0)/10 = 1.0
    if let Value::Float(f) = &normalized[2] {
        assert!((*f - 1.0).abs() < 0.001);
    }
}

#[test]
fn test_normalize_constant() {
    // 모든 값이 같으면 0.5로 반환
    let arr = vec![Value::Integer(5), Value::Integer(5), Value::Integer(5)];
    let normalized = advanced::normalize(&arr).unwrap();
    for val in normalized {
        if let Value::Float(f) = val {
            assert!((f - 0.5).abs() < 0.001);
        }
    }
}

#[test]
fn test_normalize_empty() {
    let arr: Vec<Value> = vec![];
    let result = advanced::normalize(&arr);
    assert!(result.is_ok());
    assert_eq!(result.unwrap().len(), 0);
}

// ============= 표준화 함수 테스트 =============

#[test]
fn test_standardize_basic() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
        Value::Integer(4),
        Value::Integer(5),
    ];
    let standardized = advanced::standardize(&arr).unwrap();
    assert_eq!(standardized.len(), 5);
}

#[test]
fn test_standardize_constant() {
    let arr = vec![Value::Integer(5), Value::Integer(5), Value::Integer(5)];
    let standardized = advanced::standardize(&arr).unwrap();
    for val in standardized {
        if let Value::Float(f) = val {
            assert!(f == 0.0);
        }
    }
}

// ============= 백분위수 함수 테스트 =============

#[test]
fn test_percentile_50th() {
    let arr = vec![
        Value::Integer(1),
        Value::Integer(2),
        Value::Integer(3),
        Value::Integer(4),
